import {cards,questions,scoreAnswers} from './data.mjs';
const app=document.querySelector('#app');let answers=Array(questions.length).fill(null),step=0;
const art=c=>c.image?`<div class="art" data-card-art="${c.id}"><img src="${c.image}" alt="${c.name}"></div>`:`<div class="art" data-card-art="${c.id}" role="img" aria-label="${c.name} 카드">${c.name}</div>`;
const notice=t=>document.querySelector('#notice').textContent=t;
function focus(){app.querySelector('h1,legend')?.focus();}
function go(hash){if(location.hash===hash)render();else location.hash=hash;}
function start(){answers=Array(12).fill(null);step=0;go('#quiz');}
function render(){notice('');const route=location.hash;
 if(route==='#quiz'){quiz();return;}
 if(route==='#gallery'){app.innerHTML=`<h1 tabindex="-1">일곱 가지 감정의 결</h1><p>어느 식물도 더 좋거나 특별한 등급은 없어요.</p><div class="grid">${cards.map(c=>`<a class="tile" href="#card/${c.id}">${art(c)}<strong>${c.name}</strong><p>${c.texture}</p></a>`).join('')}</div><div class="actions"><a class="button" href="${answers.some(a=>a!==null)?'#quiz':'#'}">${answers.some(a=>a!==null)?'질문으로 돌아가기':'처음으로'}</a></div>`;focus();return;}
 if(route.startsWith('#result/')||route.startsWith('#card/')){const c=cards.find(c=>c.id===route.split('/')[1]);if(c){result(c,route.startsWith('#result/'));return;}}
 app.innerHTML=`<p class="eyebrow">12개의 질문 · 약 2분</p><h1 tabindex="-1">요즘 마음은<br>어떤 결을 가지고 있나요?</h1><p>일상 속 작은 선택을 따라가며 지금의 감정을 식물 카드로 만나보세요.</p><p class="muted">정답은 없어요. 최근의 나에게 조금 더 가까운 모습을 골라주세요. 답변은 서버에 저장되지 않아요.</p><div class="actions"><button class="primary" id="start">내 감정의 결 알아보기</button></div>`;document.querySelector('#start').onclick=start;focus();}
function quiz(){const q=questions[step];app.innerHTML=`<p class="eyebrow">${step+1} / ${questions.length}</p><progress value="${step}" max="12" aria-label="완료한 질문"></progress><form><fieldset><legend tabindex="-1">${q.text}</legend><div class="options">${q.options.map((o,i)=>`<label><input type="radio" name="answer" value="${i}" ${answers[step]===i?'checked':''}><span>${o.text}</span></label>`).join('')}</div></fieldset><div class="actions"><button type="button" id="back" ${step===0?'disabled':''}>이전</button><button class="primary" id="next" ${answers[step]===null?'disabled':''}>${step===11?'결과 보기':'다음'}</button></div></form>`;
 app.querySelectorAll('input').forEach(el=>el.onchange=()=>{answers[step]=Number(el.value);document.querySelector('#next').disabled=false;});
 document.querySelector('#back').onclick=()=>{step--;quiz();};app.querySelector('form').onsubmit=e=>{e.preventDefault();if(answers[step]===null)return;if(step<11){step++;quiz();}else finish();};focus();}
function finish(){const {candidates}=scoreAnswers(answers);if(candidates.length===1){go('#result/'+candidates[0].id);return;}app.innerHTML=`<p class="eyebrow">마지막으로 한 가지만 더</p><h1 tabindex="-1">두루 닮은 마음 중,<br>지금 더 가까운 결은 무엇인가요?</h1><p>여러 감정의 결이 함께 나타났어요. 오늘 더 와닿는 문장을 골라주세요.</p><div class="options">${candidates.map(c=>`<button data-pick="${c.id}">${c.summary}</button>`).join('')}</div><button id="revise">마지막 질문으로</button>`;app.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>go('#result/'+b.dataset.pick));document.querySelector('#revise').onclick=quiz;focus();}
function result(c,isResult){app.innerHTML=`<p class="eyebrow">${isResult?'지금 마음에 가까운 식물':'식물 카드 살펴보기'}</p><h1 tabindex="-1">${c.name} · ${c.texture}</h1>${art(c)}<h2>${c.summary}</h2>${c.paragraphs.map(p=>`<p>${p}</p>`).join('')}<p class="quote">${c.note}</p><div class="actions"><button id="save">카드 이미지 저장</button><button id="share">결과 링크 공유</button><button id="retry">다시 해보기</button><a class="button" href="#gallery">일곱 식물 보기</a></div><p class="muted">${isResult?'오늘의 응답과 가까운 상징이에요. 시간이 흐르면 다른 결을 만날 수도 있어요.':'이 카드는 감상 중인 카드예요. 질문에 답하면 지금 마음에 가까운 결과를 볼 수 있어요.'}</p>`;
 document.querySelector('#retry').onclick=start;document.querySelector('#save').onclick=()=>save(c);document.querySelector('#share').onclick=async()=>{const url=new URL(location.href);url.hash='result/'+c.id;try{if(navigator.share)await navigator.share({title:`감정의 결 · ${c.name}`,text:c.summary,url:url.href});else{await navigator.clipboard.writeText(url.href);notice('결과 링크를 복사했어요.');}}catch(e){if(e.name!=='AbortError'){notice('아래 링크를 복사해주세요.');const input=document.createElement('input');input.value=url.href;input.readOnly=true;input.style.width='100%';document.querySelector('#notice').append(input);input.select();}}};focus();}
async function save(c){await document.fonts.ready;const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1350;const x=canvas.getContext('2d');x.fillStyle='#fafafa';x.fillRect(0,0,1080,1350);x.fillStyle='#252d28';x.textAlign='center';x.font='32px sans-serif';x.fillText('감정의 결',540,110);x.strokeStyle='#9aa59e';x.setLineDash([8,8]);x.strokeRect(90,180,900,660);x.font='bold 100px sans-serif';x.fillText(c.name,540,545);if(c.image){try{const img=new Image();img.crossOrigin='anonymous';img.src=c.image;await img.decode();const scale=Math.min(900/img.width,660/img.height);x.fillStyle='#fafafa';x.fillRect(90,180,900,660);x.drawImage(img,540-img.width*scale/2,510-img.height*scale/2,img.width*scale,img.height*scale);}catch{notice('그림을 불러오지 못해 이름으로 저장해요.');}}x.fillStyle='#252d28';x.font='bold 42px sans-serif';x.fillText(c.texture,540,950);x.font='32px sans-serif';x.fillText(c.summary,540,1030);x.font='28px sans-serif';x.fillText(c.note,540,1160);try{canvas.toBlob(blob=>{if(!blob){notice('저장하지 못했어요. 다시 시도해주세요.');return;}const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`감정의-결-${c.name}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);notice('카드 이미지를 저장했어요.');},'image/png');}catch{notice('이미지를 저장하지 못했어요. 이미지 접근 설정을 확인해주세요.');}}
window.addEventListener('hashchange',render);render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'complete_emotion_questions',description:'12개 질문의 선택지 번호(0~3)를 받아 감정 결과 또는 동점 선택 화면을 표시합니다.',inputSchema:{type:'object',properties:{answers:{type:'array',items:{type:'integer',minimum:0,maximum:3},minItems:12,maxItems:12}},required:['answers'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){const scored=scoreAnswers(input.answers);answers=[...input.answers];step=11;history.replaceState(null,'','#quiz');finish();return {candidates:scored.candidates.map(c=>({id:c.id,name:c.name})),needsChoice:scored.candidates.length>1};}})).catch(()=>{});}catch{}}
